-- No-calculator practice: questions whose answer needs a calculation (the exams allow no calculator),
-- and how to do that calculation by hand. Ids match production: both run the same migrations.
ALTER TABLE questions ADD COLUMN calc INTEGER NOT NULL DEFAULT 0; -- 1 = needs a calculation
ALTER TABLE questions ADD COLUMN mental TEXT; -- 'Without a calculator' tip shown with the answer

-- 357 questions tagged by hand (Biophysics, Biostatistics, Chemistry, Biochemistry, Physiology).
UPDATE questions SET calc = 1 WHERE id IN (56, 57, 72, 73, 74, 76, 77, 79, 80, 81, 82, 85, 86, 87, 95, 96, 97, 101, 102, 103, 104, 105, 106, 107, 108, 109, 110, 111, 112, 114, 115, 117, 118, 125, 126, 133, 134, 135, 136, 137, 320, 332, 333, 334, 348, 357, 362, 363, 364, 382, 383, 384, 396, 397, 399, 400, 401, 403, 404, 405, 407, 408, 409, 410, 411, 412, 415, 416, 417, 418, 419, 420, 422, 423, 424, 425, 427, 428, 429, 430, 431, 435, 436, 437, 439, 440, 442, 443, 444, 445, 446, 449, 450, 454, 455, 457, 458, 459, 460, 461, 462, 463, 464, 465, 466, 467, 469, 470, 472, 473, 474, 475, 476, 477, 478, 479, 480, 481, 482, 483, 484, 486, 498, 499, 500, 501, 502, 503, 504, 505, 506, 507, 508, 509, 510, 511, 512, 517, 518, 519, 521, 522, 527, 528, 529, 530, 531, 532, 533, 534, 535, 536, 539, 541, 542, 549, 550, 551, 554, 555, 556, 557, 558, 559, 560, 561, 562, 567, 568, 569, 570, 571, 574, 575, 576, 577, 578, 579, 580, 585, 586, 587, 588, 589, 590, 591, 592, 593, 594, 595, 596, 597, 598, 599, 600, 604, 605, 606, 607, 610, 611, 612, 613, 614, 615, 616, 617, 618, 619, 621, 622, 623, 624, 625, 626, 628, 630, 631, 632, 633, 635, 661, 662, 663, 664, 665, 666, 667, 668, 670, 671, 672, 673, 675, 679, 680, 682, 684, 685, 687, 688, 689, 690, 691, 692, 693, 706, 707, 708, 709, 710, 718, 729, 730, 731, 732, 733, 734, 735, 736, 737, 738, 739, 740, 745, 746, 747, 748, 749, 750, 751, 753, 769, 770, 771, 774, 785, 789, 790, 792, 795, 796, 797, 798, 800, 801, 802, 803, 804, 805, 806, 808, 814, 815, 824, 825, 828, 830, 832, 833, 834, 835, 836, 837, 840, 841, 843, 1100, 1140, 1147, 1149, 1150, 1151, 1152, 1153, 1159, 1161, 1163, 1167, 1168, 1214, 1215, 1217, 1218, 1219, 1222, 1226, 1228, 1229, 1230, 1231, 1234, 1235, 1237, 1239, 1240, 1381, 1382, 1383, 1389, 1392, 1394, 1633, 1634, 1635, 1636, 1637, 1638, 1639, 1726, 1740, 1748, 1749, 1752, 1753, 1756, 1758);

-- Biophysics: 100 tips.
UPDATE questions SET mental = 'Convert, then work in powers of ten: 2 bar = 2×10⁵ Pa, 1 cm² = 10⁻⁴ m², 5 mm = 5×10⁻³ m. Multiply the numbers (2 × 5 = 10) and add the exponents (5 − 4 − 3 = −2): 10×10⁻² = 0.1 J = 100 mJ.' WHERE id = 72;
UPDATE questions SET mental = '150 Torr ≈ 1/5 atm ≈ 20 000 Pa (150/760 ≈ 0.197). RT at 298 K ≈ 2 480. n ≈ 20 000 × 0.08 / 2 480 = 1 600/2 480 ≈ 0.65 mol → only B (646 mmol) is close.' WHERE id = 73;
UPDATE questions SET mental = 'Don''t redo the gas law: at fixed V and T, P is proportional to n. P = 150 Torr × 0.25/0.646 ≈ 150 × 0.39 ≈ 58 Torr.' WHERE id = 74;
UPDATE questions SET mental = '47.4/158 = 0.3 (158 × 3 = 474). 45 mL × 2 mol/L = 90 mmol. Particles: 0.3 × 2 + 0.09 × 4 = 0.6 + 0.36 = 0.96 osm/L.' WHERE id = 76;
UPDATE questions SET mental = 'Shortcuts worth memorising: I = C for a 1:1 salt (KMnO₄), I = 3C for CaCl₂-type salts, I = 6C for H₃PO₄ / Na₃PO₄-type. Here 0.3 + 6 × 0.09 = 0.3 + 0.54 = 0.84.' WHERE id = 77;
UPDATE questions SET mental = '1.86 × 0.1 = 0.186, and 0.186 × 3.5 ≈ 0.65, so i ≈ 3.44. Al₂(SO₄)₃ gives 5 ions: α = (i − 1)/4 ≈ 2.44/4 ≈ 0.61.' WHERE id = 79;
UPDATE questions SET mental = 'D ∝ T, so multiply by 310/273 ≈ 1.135. 1.22 × 1.135 ≈ 1.385×10⁻¹⁰. The trap is the notation: 1.39×10⁻¹⁰ is written 13.9×10⁻¹¹.' WHERE id = 80;
UPDATE questions SET mental = 'Set the two osmotic loads equal: 0.15/(L − x) = 0.3/(L + x) → L + x = 2(L − x) → x = L/3 ≈ 16.7 cm. No decimals needed: it is a ratio of 1 to 2.' WHERE id = 81;
UPDATE questions SET mental = 'Factor C out and add fractions: 1 + 1/2 + 1/3 = 11/6. Then 11/6 × 3 = 11/2 = 5.5 µF.' WHERE id = 82;
UPDATE questions SET mental = '[Na⁺]ᵢᵢ = 0.16/0.457 ≈ 0.35 (0.457 × 0.35 = 0.16). Electroneutrality in ii: z·Cp = 0.457 − 0.350 = 0.107, so Cp = 0.107/18 ≈ 0.006 osmol/L = 6 mosmol/L (18 × 6 = 108).' WHERE id = 85;
UPDATE questions SET mental = 'Use ln 3 ≈ 1.10 and ln 1.4 = ln 7 − ln 5 ≈ 1.95 − 1.61 = 0.34. t = 1.10/0.336 ≈ 3.27 h, and 0.27 h × 60 ≈ 16 min → 3 h 16 min.' WHERE id = 86;
UPDATE questions SET mental = 'Memorise RT/F ≈ 25.8 mV at 27 °C (26.7 mV at 37 °C). ln 6 = ln 2 + ln 3 = 0.69 + 1.10 = 1.79. 25.8 × 1.79 ≈ 46 mV.' WHERE id = 87;
UPDATE questions SET mental = 'RT at 343 K ≈ 8.31 × 343 ≈ 2 850. n = 35 000 × 0.025/2 850 = 875/2 850 ≈ 0.31 mol, × 18 ≈ 5.5 g of vapour. Liquid left = 9 − 5.5 = 3.5 g.' WHERE id = 396;
UPDATE questions SET mental = '9 g = 0.5 mol. RT at 373 K ≈ 3 100. P = 0.5 × 3 100/0.025 = 1 550 × 40 = 62 000 Pa = 0.62 bar, below 1 bar, so it is all vapour.' WHERE id = 397;
UPDATE questions SET mental = 'Millimoles = mL × mol/L: HCl 15 × 2 = 30, H₂SO₄ 30 × 1 = 30. Particles: 30 × 2 + 30 × 3 = 150 mosm/L.' WHERE id = 399;
UPDATE questions SET mental = 'i = 1 + α(β − 1) = 1 + 0.6 × 3 = 2.8. 0.65 × 2.8 = 0.65 × 3 − 0.65 × 0.2 = 1.95 − 0.13 = 1.82.' WHERE id = 400;
UPDATE questions SET mental = '2.34/58.5 = 0.04 (58.5 × 4 = 234) and 3.33/111 = 0.03. I = C for NaCl and 3C for CaCl₂: 0.04 + 0.09 = 0.13.' WHERE id = 401;
UPDATE questions SET mental = '1.86 × 0.2 = 0.372, and 0.372 × 1.75 ≈ 0.65, so i ≈ 1.75. CaCl₂ gives 3 ions: α = (1.75 − 1)/2 ≈ 0.37.' WHERE id = 403;
UPDATE questions SET mental = 'At balance R × R = R₁ × R₂ = 64 × 16 = 1 024 = 32². Knowing 32² = 1 024 gives R = 32 Ω directly.' WHERE id = 404;
UPDATE questions SET mental = 'σ = L/(R·S) in SI: L = 0.12 m, S = 10⁻³ m², so R·S = 0.032. 0.12/0.032 = 120/32 = 3.75.' WHERE id = 405;
UPDATE questions SET mental = 'RT at 300 K ≈ 2 493 ≈ 2 500. Δω = 750/2 500 = 0.3 osmol/m³. Water goes toward the more concentrated side, so B = 1.8 + 0.3 = 2.1.' WHERE id = 407;
UPDATE questions SET mental = 'Donnan product: [Cl⁻]II = 0.57²/0.714. 57² = 3 249, so 0.325/0.714 ≈ 0.455 (0.714 × 0.455 ≈ 0.325). Watch the units: 455 mosmol/L = 0.455 osmol/L.' WHERE id = 408;
UPDATE questions SET mental = 'ω = 2π × 50 000/60 ≈ 5 236 rad/s, ω² ≈ 2.74×10⁷. sω²t = 10⁻¹² × 2.74×10⁷ × 4 500 ≈ 0.123. For a small exponent e^y ≈ 1 + y + y²/2 ≈ 1.131, so x ≈ 11.3 cm: about 13 mm travelled.' WHERE id = 409;
UPDATE questions SET mental = 'Three pairs, each kq²/a, with q² = 16×10⁻¹². 3 × 9 × 16 = 432, and 10⁹ × 10⁻¹² = 10⁻³: 0.432 J.' WHERE id = 410;
UPDATE questions SET mental = 'Reduce the circuit branch by branch: n equal resistors in parallel give R/n, and two in parallel give R₁R₂/(R₁ + R₂), e.g. 9 ∥ 4.5 = 40.5/13.5 = 3 Ω. Finally 18 ∥ 9 = 162/27 = 6 Ω.' WHERE id = 411;
UPDATE questions SET mental = 'Lapicque: I = I₀(1 + τ/t). With t = τ/5, τ/t = 5, so I = 6 I₀. Just substitute the ratio, there is nothing to compute.' WHERE id = 412;
UPDATE questions SET mental = 'Partial pressure = mole fraction × total: B has 3 of the 5 moles, 3/5 × 3 = 1.8 bar; A gets 2/5 × 3 = 1.2 bar (not 1).' WHERE id = 415;
UPDATE questions SET mental = '400 Torr = 10/19 atm ≈ 0.526 atm ≈ 53 300 Pa. RT at 290 K ≈ 2 410. n ≈ 53 300 × 0.02/2 410 = 1 066/2 410 ≈ 0.44 mol; × 74 ≈ 32.7 g.' WHERE id = 416;
UPDATE questions SET mental = 'No gas-law numbers needed: same n and T, so PV is constant. 400 × 20/25 = 400 × 0.8 = 320 Torr.' WHERE id = 417;
UPDATE questions SET mental = 'i = 1 + α(β − 1) = 1 + 0.6 × 2 = 2.2, which already rules out A (3.2) and B (2.5). 2 L × 1 mol/L = 2 mol, × 2.2 = 4.4 N kinetic units.' WHERE id = 418;
UPDATE questions SET mental = '11.1/111 = 0.1 mol; 45 mL × 1 mol/L = 45 mmol. 100 × 3 + 45 × 3 = 300 + 135 = 435 mosm/L.' WHERE id = 419;
UPDATE questions SET mental = '3.28/164 = 0.02 (164 × 2 = 328) and 3.33/111 = 0.03. I = 6C for Na₃PO₄ and 3C for CaCl₂: 0.12 + 0.09 = 0.21.' WHERE id = 420;
UPDATE questions SET mental = 'Everything in powers of ten: ΔC = 40 mmol/L = 40 mol/m³, S = 4×10⁻⁴ m², so S·ΔC = 1.6×10⁻². 4.2×10⁻¹²/1.6×10⁻² ≈ 2.6×10⁻¹⁰ = 0.26×10⁻⁹ m/s.' WHERE id = 422;
UPDATE questions SET mental = 'Urine osmolarity = 1.9/1.86 ≈ 1.02 osmol/L (1.86 × 1.02 ≈ 1.90). Over 0.8 L that is ≈ 0.82 mol, all counted as urea: the closest option is A (0.814 mol).' WHERE id = 423;
UPDATE questions SET mental = 'W = n·RT·ln(ωu/ωpl) per day. The ratio comes straight from the depressions (K cancels): 1.9/0.56 ≈ 3.4, and ln 3.4 ≈ 1.10 + 0.12 = 1.22. RT at 310 K ≈ 2 576. 0.814 × 2 576 × 1.22 ≈ 2 560 J/day. ÷ 86 400 s ≈ 29.6 mW for both kidneys, so ≈ 14.8 mW each.' WHERE id = 424;
UPDATE questions SET mental = 'R = L/(σS): σS = 16.3 × 12×10⁻⁴ ≈ 0.0196. 0.1/0.0196 ≈ 5.1 Ω (0.0196 × 5 = 0.098).' WHERE id = 425;
UPDATE questions SET mental = 'Units first: 0.104 osmol/L = 104 osmol/m³. RT at 300 K ≈ 2 493. 104 × 2 493 ≈ 259 000 Pa; ÷ 101 325 ≈ 2.56 atm.' WHERE id = 427;
UPDATE questions SET mental = 'Osmolarity of B = 0.67/1.8 ≈ 0.372 osmol/L (1.8 × 0.372 = 0.67). NaCl at 170 mmol/L gives 340 mosm/L, so the protein adds 32 mosm/L. RNa₁₅ releases 16 particles: 32/16 = 2 mmol/L.' WHERE id = 428;
UPDATE questions SET mental = 'Let x mmol/L of Na⁺ (with Cl⁻) move from B to A. B starts with 170 + 15 × 2 = 200 mmol/L of Na⁺. Donnan: (170 + x)² = (200 − x)(170 − x). The x² cancel: 28 900 + 340x = 34 000 − 370x → 710x = 5 100 → x ≈ 7.2 mmol/L.' WHERE id = 429;
UPDATE questions SET mental = 'ω = 2π × 1 000 ≈ 6 283 rad/s, ω² ≈ 3.95×10⁷. sω²t = 10⁻¹² × 3.95×10⁷ × 3 600 ≈ 0.142. e^0.142 ≈ 1 + 0.142 + 0.010 = 1.152, so x ≈ 11.5 cm: ≈ 15 mm travelled, closest to E.' WHERE id = 430;
UPDATE questions SET mental = 'Each of the three branches is 3 Ω (3; 1.5 + 1.5; 1 + 1 + 1), and n equal resistors in parallel give R/n: 3/3 = 1 Ω.' WHERE id = 431;
UPDATE questions SET mental = 'Mole fraction × total pressure: C has 5 of the 10 moles, ½ × 150 = 75 Torr; B gets 3/10 × 150 = 45 Torr (not 50).' WHERE id = 435;
UPDATE questions SET mental = '31.8/760 ≈ 0.042 atm ≈ 4 240 Pa. RT at 303 K ≈ 2 520. n ≈ 4 240 × 0.1/2 520 = 424/2 520 ≈ 0.168 mol; × 18 ≈ 3.03 g.' WHERE id = 436;
UPDATE questions SET mental = '2 g is less than the 3.03 g that saturate the enclosure, so it all vaporizes and P is proportional to the mass: 31.8 × 2/3.03 ≈ 31.8 × 0.66 ≈ 21 Torr.' WHERE id = 437;
UPDATE questions SET mental = '22.2/111 = 0.2 mol; 35 mL × 1 mol/L = 35 mmol. 200 × 3 + 35 × 4 = 600 + 140 = 740 mosm/L.' WHERE id = 439;
UPDATE questions SET mental = 'I = 3C for CaCl₂ and 6C for H₃PO₄ (3 H⁺ + PO₄³⁻): 3 × 0.2 + 6 × 0.035 = 0.6 + 0.21 = 0.81.' WHERE id = 440;
UPDATE questions SET mental = '1.86 × 0.1 = 0.186, and 0.186 × 2.4 ≈ 0.446, so i ≈ 2.42. CaCl₂ gives 3 ions: α = (2.42 − 1)/2 ≈ 0.71.' WHERE id = 442;
UPDATE questions SET mental = '1.6/1.86 ≈ 0.86 (1.86 × 0.86 = 1.60). Over 1 L: 0.86 osmol = 860 mmol.' WHERE id = 443;
UPDATE questions SET mental = 'σ = L/(R·S): R·S = 7.3 × 16×10⁻⁴ ≈ 0.0117. 0.1/0.0117 ≈ 8.56 (0.0117 × 8.5 ≈ 0.0994).' WHERE id = 444;
UPDATE questions SET mental = 'Capacitors combine the opposite way to resistors: in parallel they add, in series 1/C = 1/C₁ + 1/C₂ (for two: C₁C₂/(C₁ + C₂)). Reduce the figure branch by branch and keep fractions until the end.' WHERE id = 445;
UPDATE questions SET mental = 'Δω = 0.214 − 0.115 = 0.099 osmol/L = 99 osmol/m³. RT at 300 K ≈ 2 500: 99 × 2 500 ≈ 247 000 Pa ≈ 2.47 bar.' WHERE id = 446;
UPDATE questions SET mental = 't = 1 h × ln 1.8/ln 1.25. ln 1.8 = ln 9 − ln 5 ≈ 2.20 − 1.61 = 0.59; ln 1.25 = ln 5 − ln 4 ≈ 1.61 − 1.39 = 0.22. The ratio ≈ 2.6–2.7 h, and only A (2 h 38 min) fits.' WHERE id = 449;
UPDATE questions SET mental = 'RT/F at 290 K ≈ 25 mV. ln(4/100) = ln 4 − ln 100 ≈ 1.39 − 4.61 = −3.22. 25 × (−3.22) ≈ −80 mV.' WHERE id = 450;
UPDATE questions SET mental = '1 cal ≈ 4.18 J and 1 J = 10⁷ erg: 2 × 4.184 = 8.368 J = 8.368×10⁷ erg. Sanity check: an erg is tiny, so the erg value must be big (10⁷, not 10⁻⁷).' WHERE id = 1140;
UPDATE questions SET mental = 't = 100 × 2^(1/4), and 2^(1/4) = √√2 = √1.414 ≈ 1.19 (1.19² ≈ 1.42). So t ≈ 119 °C.' WHERE id = 1147;
UPDATE questions SET mental = 'h = P/(ρg) = 101 325/9 810 ≈ 10.3 m. Worth memorising: about 10 m of water ≈ 1 atm (76 cm of mercury).' WHERE id = 1149;
UPDATE questions SET mental = 'Psat·V = 46 600 × 0.01 = 466 J. RT at 353 K ≈ 2 930. 466/2 930 ≈ 0.159 mol, × 18 ≈ 2.86 g of vapour. Liquid left = 4 − 2.86 = 1.14 g.' WHERE id = 1150;
UPDATE questions SET mental = '4/18 ≈ 0.222 mol. RT at 373 K ≈ 3 100. P = 0.222 × 3 100/0.01 ≈ 68 900 Pa ≈ 0.69 bar, below 1 bar, so it is all unsaturated vapour.' WHERE id = 1151;
UPDATE questions SET mental = '0.5/18 ≈ 0.028 mol. × RT at 353 K (≈ 2 930) ≈ 81 J; ÷ 0.01 m³ ≈ 8 100 Pa ≈ 0.08 bar, far below 0.466 bar, so everything vaporizes.' WHERE id = 1152;
UPDATE questions SET mental = '1.2⁴ = 1.44² ≈ 2.07 bar = 207 000 Pa. × 0.002 m³ ≈ 414 J; RT at 393 K ≈ 3 270. 414/3 270 ≈ 0.127 mol, × 18 ≈ 2.3 g.' WHERE id = 1153;
UPDATE questions SET mental = 'I = 3C for CaCl₂ = 6×10⁻³. √(6×10⁻³) = √60 × 10⁻² ≈ 0.0775, so log γ ≈ −0.039. For small x, 10^(−x) ≈ 1 − 2.3x, so γ ≈ 0.91. a ≈ 0.91 × 4×10⁻³ ≈ 3.65×10⁻³ → D.' WHERE id = 1159;
UPDATE questions SET mental = '5.85/58.5 = 0.1 and 9.5/95 = 0.1. I = C for NaCl and 3C for MgCl₂: 0.1 + 0.3 = 0.40.' WHERE id = 1161;
UPDATE questions SET mental = 'I = 3C = 3×10⁻³, and √(3×10⁻³) = √30 × 10⁻² ≈ 0.055. log γ = −0.5 × 2² × 0.055 ≈ −0.11. 10^(−0.1) ≈ 0.79, so 10^(−0.11) is a little lower: only B (0.777) fits.' WHERE id = 1163;
UPDATE questions SET mental = 'i = 1 + α(β − 1) = 1 + 0.8 × 2 = 2.6. 2.6 × 0.2 = 0.52 osmol/L.' WHERE id = 1167;
UPDATE questions SET mental = '5.85/58.5 = 0.1, 18/180 = 0.1, 20 mL × 1 mol/L = 20 mmol. In mosm: 100 × 2 + 100 × 1 + 20 × 3 = 360.' WHERE id = 1168;
UPDATE questions SET mental = 'i = 1 + 0.2 × (2 − 1) = 1.2, and 1.2 × 0.1 = 0.12 osmol/L.' WHERE id = 1214;
UPDATE questions SET mental = 'ω/C = 0.5/0.2 = 2.5 = 1 + 2α, so α = 0.75. Any α above 1 (like C, 1.5) is impossible.' WHERE id = 1215;
UPDATE questions SET mental = 'NaCl: 0.1 × 2 = 0.20. HCOOH: 0.2 × (1 + 0.1) = 0.22. Total 0.42 osmol/L.' WHERE id = 1217;
UPDATE questions SET mental = '11.7/58.5 = 0.2 (58.5 × 2 = 117) and 9/180 = 0.05. 0.2 × 2 + 0.05 = 0.45 osmol/L.' WHERE id = 1218;
UPDATE questions SET mental = '14.2/142 = 0.1; 25 mL × 2 mol/L = 50 mmol. 100 × 3 + 50 × 4 = 500 mosm/L.' WHERE id = 1219;
UPDATE questions SET mental = '3 ions × 0.3 = 0.9, and a molality gives an osmolality in osmol/kg, not osmol/L: read the units before the numbers.' WHERE id = 1222;
UPDATE questions SET mental = 'ω = 2 × 0.1 = 0.2; 0.52 × 0.2 = 0.104 °C, added to 100 °C (a solution boils higher than water).' WHERE id = 1226;
UPDATE questions SET mental = 'ω = 0.3; 1.86 × 0.3 = 0.558 ≈ 0.56, with a minus sign. Worth memorising: −0.56 °C is the normal freezing-point depression of plasma.' WHERE id = 1228;
UPDATE questions SET mental = '0.4836/1.86 = 0.26 (1.86 × 0.26 = 0.4836 exactly). 0.26/0.1 = 2.6 = 1 + 2α, so α = 0.8.' WHERE id = 1229;
UPDATE questions SET mental = '1.023/1.86 = 0.55 (1.86 × 0.55 = 1.023). 0.55/0.5 = 1.1 = 1 + α, so α = 0.1.' WHERE id = 1230;
UPDATE questions SET mental = 'Only the excess counts: 0.65 − 0.56 = 0.09 °C. 0.09/1.86 ≈ 0.048 osmol/L (1.86 × 0.05 = 0.093). × 46 ≈ 2.2 g/L.' WHERE id = 1231;
UPDATE questions SET mental = 'ω₁ = 0.15, ω₂ = 0.10, so Δω = 0.05 osmol/L = 50 osmol/m³. RT at 300 K ≈ 2 500: 50 × 2 500 = 125 kPa, and water goes toward the more concentrated (1).' WHERE id = 1234;
UPDATE questions SET mental = 'RT at 300 K = 2 493, so 249 300/2 493 = 100 osmol/m³ = 0.1 osmol/L (the data are chosen for this). Water leaves (1), so (2) is more concentrated: 0.3 + 0.1 = 0.4.' WHERE id = 1235;
UPDATE questions SET mental = 'Add only the effective osmoles: urea crosses the membrane and doesn''t count, leaving 150 < 300 mosmol/L, so the solution is hypotonic and water enters.' WHERE id = 1237;
UPDATE questions SET mental = 'σ·ω = 0.4 × 100 = 40 osmol/m³. × RT (≈ 2 493) ≈ 99 700 Pa ≈ 99.7 kPa.' WHERE id = 1239;
UPDATE questions SET mental = 'Effective osmolarity = 0.5 × 200 + 0 × 100 = 100 osmol/m³. × RT (≈ 2 493) ≈ 249 kPa.' WHERE id = 1240;
UPDATE questions SET mental = 'ωu = 0.48/1.2 = 0.4 osmol/L and ωpl = 0.3/60 = 0.005 osmol/L. 0.4/0.005 = 400/5 = 80.' WHERE id = 1381;
UPDATE questions SET mental = 'ln 80 = ln 8 + ln 10 ≈ 2.08 + 2.30 = 4.38. RT at 310 K ≈ 2 576, and 0.48 × 2 576 ≈ 1 237. × 4.38 ≈ 5 420 J/day. Per kidney per second: 5 420/(2 × 86 400) ≈ 0.0314 W = 31.4 mW.' WHERE id = 1382;
UPDATE questions SET mental = 'Only the logs matter: ln 120 = ln 12 + ln 10 ≈ 2.48 + 2.30 = 4.79 and ln 60 = ln 6 + ln 10 ≈ 1.79 + 2.30 = 4.09. 4.79/4.09 ≈ 1.17. Shortcut: the difference is ln 2 = 0.69, and 0.69/4.09 ≈ 0.17.' WHERE id = 1383;
UPDATE questions SET mental = 'Total moles over total volume: 0.2 × 1 + 0.04 × 3 = 0.32 mol in 4 L = 0.08 mol/L. Check: the answer must lie between 0.04 and 0.2.' WHERE id = 1389;
UPDATE questions SET mental = 'Convert first: ΔC = 40 mol/m³, S′ = 2×10⁻⁴ m², l = 10⁻⁵ m. Numbers: 1 × 2 × 40 = 80; exponents: −9 − 4 + 5 = −8. 80×10⁻⁸ = 8×10⁻⁷ mol/s.' WHERE id = 1392;
UPDATE questions SET mental = 'S = 10 cm² = 10⁻³ m². 8×10⁻⁷/10⁻³ = 8×10⁻⁴: just subtract the exponents.' WHERE id = 1394;
UPDATE questions SET mental = 'D ∝ M^(−1/3), and the cube root of 8 is 2, so D is divided by 2.' WHERE id = 1633;
UPDATE questions SET mental = 'D ∝ 1/η, so divide by 1.5: 6/1.5 = 4 → 4×10⁻¹¹ m²/s.' WHERE id = 1634;
UPDATE questions SET mental = 'kT = 1.38×10⁻²³ × 300 = 4.14×10⁻²¹. 6π ≈ 18.85, and 18.85 × 10⁻³ × 2×10⁻¹¹ ≈ 3.77×10⁻¹³. 4.14/3.77 ≈ 1.1, so r ≈ 1.1×10⁻⁸ m = 11 nm.' WHERE id = 1635;
UPDATE questions SET mental = 'ΔC = 60 mol/m³ and S = 5×10⁻⁴ m², so S·ΔC = 3×10⁻². 9×10⁻¹²/3×10⁻² = 3×10⁻¹⁰ = 0.3×10⁻⁹ m/s.' WHERE id = 1636;
UPDATE questions SET mental = 'D = P·l ÷ pore fraction: 0.3×10⁻⁹ × 20×10⁻⁶ = 6×10⁻¹⁵, and dividing by 0.02 means multiplying by 50: 3×10⁻¹³ m²/s.' WHERE id = 1637;
UPDATE questions SET mental = 'P·S = 4×10⁻⁶ × 10⁻³ = 4×10⁻⁹ m³/s; ΔC = 0.3 mol/L = 300 mol/m³. 4 × 300 = 1 200, so 1.2×10⁻⁶ mol/s = 1.2 µmol/s.' WHERE id = 1638;
UPDATE questions SET mental = 'Dm/l = 8×10⁻¹⁰/4×10⁻⁵ = 2×10⁻⁵ m/s. × S (1 m²) × C₀ (2 g/L = 2×10³ g/m³) = 4×10⁻² g/s = 40 mg/s.' WHERE id = 1639;
UPDATE questions SET mental = 'Count charges: cations 2 Na⁺ + 2 K⁺ = 4 Eq, anions SO₄²⁻ (2 Eq) + 2 Cl⁻ = 4 Eq. Ce = 4 + 4 = 8 Eq/l.' WHERE id = 1748;
UPDATE questions SET mental = 'Concentration first: 0.1 mol in 0.5 l = 0.2 mol/l. Then [Cl⁻] = 3 × 0.2 = 0.6, Ce⁺ = 3 × 0.2 = 0.6 = Ce⁻, Ce = 1.2.' WHERE id = 1749;
UPDATE questions SET mental = 'zC′ = 0.04, so 4C + zC′ = 0.44; zCC′ = 20 × 0.1 × 0.002 = 0.004. x = 0.004/0.44 = 1/110 ≈ 9.1 mmol/l. [Cl⁻]₂ = 100 − 9.1 = 90.9 mmol/l.' WHERE id = 1752;
UPDATE questions SET mental = '0.15² = 0.0225, and 0.0225/0.18 = 0.125 (0.18 × 1/8 = 0.0225). Protein charge: 0.18 − 0.125 = 0.055 Eq/l = 55 mEq/l.' WHERE id = 1753;
